  /**
   * What is due on a claim: the due fixed when it was settled, or else the greater of the floor in
   * force on the claim's date and its figure — the rate figure its person's last statement bound it to,
   * or else its amount at the rate the person's grade has in force on the claim's date (n/a when it is
   * dated before every rate) — with its late charge (at the late percent in force on each 30-day
   * boundary) on top while it is overdue.
   */
  protected dueOf(claim: ClaimView): string {
    const late = { history: this.session.latePctHistory(), today: this.session.today() ?? '', grace: this.graceOf(claim) };
    const floor = cents(valueOn(this.session.floorHistory(), claim.date, '1.00'));
    const halfUp = roundsHalfUp(claim, this.claims(), this.session.policyDate(), late.today);
    const figure = claimDueCents(claim, this.rates(), gradeOn(this.grades(), claim.date), floor, late, halfUp, this.inherited());
    return figure === null ? NO_RATE : money(figure);
  }

  /** A claim's due-by, fixed when it was added. */
  protected dueByOf(claim: ClaimView): string {
    return dueBy(claim);
  }

  /** Whether a claim is OPEN and due by a date (plus its grace days) before the sheet's today. */
  protected overdueOf(claim: ClaimView): boolean {
    return overdue(claim, this.session.today() ?? '', this.graceOf(claim));
  }

  /** A claim's grace days: those the person's grade in force on its date has in force then. */
  private graceOf(claim: ClaimView): number {
    return graceOn(this.session.graceHistory(), gradeOn(this.grades(), claim.date), claim.date);
  }

  /** Whether a claim is deferred on the sheet's today. */
  protected deferredOf(claim: ClaimView): boolean {
    return deferred(claim, this.session.today() ?? '');
  }

  /** The name of the period a claim's due-by falls in; empty when it falls in none. */
  protected periodOf(claim: ClaimView): string {
    return periodOn(this.periods(), claim.dueBy)?.name ?? '';
    return money(this.personPeriodCents().get(period.id)?.get(person.id) ?? 0);
  }

  /** A person's excess: by how much the sum of their figures is above the cap, else 0.00 (n/a is not capped). */
  protected excessOf(person: PersonView): string {
    const sum = this.dueSumCents(person);
    const cap = this.capCents();
    return money(sum !== null && cap !== null && sum > cap ? sum - cap : 0);
  }

  /** The sum of a person's due figures in whole cents before the cap, or null (n/a; see dueTotalCents). */
  private dueSumCents(person: PersonView): number | null {
    const dues = this.countingOf(person.id).map((c) => this.dueCents(c, person));
    if (this.pctOf(this.gradeOf(person)) === null && dues.every((d) => d === null)) return null;
    return dues.reduce<number>((sum, d) => sum + (d ?? 0), 0);
  }

  /**
   * A claim's due in whole cents at the grade its person has in force on its date, with the floor
   * in force on its date and the late percent on each 30-day boundary (see claimDueCents).
   */
  private dueCents(claim: ClaimView, person: PersonView): number | null {
    const halfUp = roundsHalfUp(claim, this.claimsOf(person.id), this.session.policyDate(), this.today());
    const floor = cents(valueOn(this.session.floorHistory(), claim.date, '1.00'));
    const late = { history: this.session.latePctHistory(), today: this.today(), grace: this.graceOf(claim, person) };
    return claimDueCents(claim, this.rates(), gradeOn(person.grades, claim.date), floor, late, halfUp, this.inherited());
  }

  /** A person's patrons, each as their name and share, sorted by name, comma and space separated. */
  protected patronsOf(person: PersonView): string {
    return this.patronShares(person)
      .map(({ patron, share }) => ({ name: patron.name, text: `${patron.name} ${money(share)}` }))
      .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
      .map((p) => p.text)
      .join(', ');
  }

  /**
   * A person's backing: over their patrons, the settled figures of the patron's SETTLED claims dated
   * within the 90 days up to and including the sheet's today, each at its frozen figure (one with none
   * adds nothing), times the patron's share over 100, rounded half to even.
   */
  protected backingOf(person: PersonView): string {
    return money(
      this.patronShares(person).reduce((sum, { patron, share }) => sum + shareOf(this.recentSettledCents(patron.id), share), 0),
    );
  }
  return best === null ? start : best.value;
}

export interface SheetView {
  id: string;
  /** The sheet's today (yyyy-mm-dd): every date-dependent decision and default date uses it. */
  today: string;
  /** The sheet's floor in force on its today, with two decimals. */
  floor: string;
  /** The sheet's terms in force on its today, in days. */
  terms: number;
  /** The sheet's late percent in force on its today, with two decimals. */
  latePct: string;
  /** The sheet's policy date (yyyy-mm-dd); null when blank, the sheet's today then being the policy date. */
  policyDate: string | null;
  /** The sheet's cap in force on its today, with two decimals: a person's due-total is at most it; null when there is none. */
  cap: string | null;
  /** The floor's values by from-date, its starting value first. */
  floorHistory: DatedValue[];
  /** The late percent's values by from-date, its starting value first. */
  latePctHistory: DatedValue[];
  /** Whether the sheet is archived: everything stays visible but nothing on it may change. */
  archived: boolean;
  /** Each grade's grace values by from-date (a value null when none), its starting value (none) first. */
  graceHistory: Record<string, DatedValue[]>;
  /** The number of the sheet's last settle batch; null (or absent) when there has been none. */
  lastSettleBatch?: number | null;
  /** The sheet's pot with two decimals: split among each balanced pool's members as their cuts; null when there is none. */
  pot?: string | null;
  /** The parent sheet's id: its rates apply where this sheet has none in force; null when there is none. */
  parent?: string | null;
  /** The month, 1 to 12, the sheet's fiscal year starts in. */
  fiscalStartMonth: number;
}

